      "description": "La Fundación Nacional para la Ciencia y el Telescopio del Horizonte de Sucesos (EHT) han contribuido en observaciones que rompen paradigmas sobre el colosal agujero negro en el centro de la lejana galaxia Messier 87. Esta imagen del M87* proviene de observaciones del EHT realizadas el 11 de abril de 2017 y es un ejemplar representativo de las imágenes obtenidas durante la campaña de 2017. La imagen es el resultado de combinar tres métodos distintos de generación de imágenes tras convolucionar cada uno con un núcleo gaussiano circular para producir resoluciones equiparables. La imagen se muestra en unidades de temperatura de brillo, T b = S λ 2 / 2 k B Ω , donde S es la densidad de flujo, λ es la longitud de onda de observación, k B es la constante de Boltzmann y Ω es el ángulo sólido del elemento de resolución.",
